import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Financial Forecast — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"financial-forecast-01-overview-and-concepts.md","filePath":"financial-forecast-01-overview-and-concepts.md"}'),o={name:"financial-forecast-01-overview-and-concepts.md"};function s(r,e,d,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="financial-forecast-—-overview-concepts" tabindex="-1">Financial Forecast — Overview &amp; Concepts <a class="header-anchor" href="#financial-forecast-—-overview-concepts" aria-label="Permalink to &quot;Financial Forecast — Overview &amp; Concepts&quot;">​</a></h1><p><em>What it is, why it matters, and how it fits into Lodestone</em></p><hr><h2 id="what-is-financial-forecast" tabindex="-1">What Is Financial Forecast? <a class="header-anchor" href="#what-is-financial-forecast" aria-label="Permalink to &quot;What Is Financial Forecast?&quot;">​</a></h2><p>Financial Forecast is a module within Lodestone that lets product managers model the financial impact of building a Feature — before the Feature is built. It produces standard financial metrics (NPV, ROI, IRR, payback period) from structured assumptions about what the Feature will cost and what it will generate.</p><p>It lives on the <strong>Feature Detail page</strong>, under a dedicated Financial Forecast tab. Every Feature can have one or more financial models. A model is built from a set of <strong>assumptions</strong> — individual estimates about revenue, costs, and their timing — that Lodestone aggregates into a complete financial picture.</p><hr><h2 id="why-financial-forecast-exists" tabindex="-1">Why Financial Forecast Exists <a class="header-anchor" href="#why-financial-forecast-exists" aria-label="Permalink to &quot;Why Financial Forecast Exists&quot;">​</a></h2><p>Product decisions are typically framed in terms of customer value, strategic fit, and engineering effort. Financial impact — the actual expected return on a feature investment — is often missing from the conversation, or present only as rough intuition.</p><p>Financial Forecast changes this. It gives PMs a structured way to say: &quot;Based on what we believe about this Feature, here is what it is likely to cost and return over time, and here is what we&#39;re uncertain about.&quot; That kind of analysis changes how prioritization conversations happen — especially with finance, executive, and board audiences.</p><p>The module is designed to be useful without requiring a finance background. You don&#39;t need a spreadsheet or a financial model template — you work directly in Lodestone, using the same Feature context you&#39;ve already built.</p><hr><h2 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h2><h3 id="financial-model" tabindex="-1">Financial Model <a class="header-anchor" href="#financial-model" aria-label="Permalink to &quot;Financial Model&quot;">​</a></h3><p>A financial model is the container for a Feature&#39;s forecast. It has a name, a discount rate (for NPV calculation), optional context notes, and a collection of assumptions. A Feature can have multiple models — for example, a conservative model and an optimistic model.</p><p>By convention, models are named <code>[Feature Name] Financial Forecast</code> by default, though they can be renamed.</p><h3 id="assumptions" tabindex="-1">Assumptions <a class="header-anchor" href="#assumptions" aria-label="Permalink to &quot;Assumptions&quot;">​</a></h3><p>Assumptions are the individual estimates that make up a model. Each assumption represents one driver of financial impact — a revenue increase, a cost reduction, a new expense, or a cost savings. Assumptions have:</p><table tabindex="0"><thead><tr><th>Field</th><th>What it captures</th></tr></thead><tbody><tr><td>Name</td><td>What this assumption represents (e.g. &quot;New subscription revenue&quot;)</td></tr><tr><td>Category</td><td>The type of impact: Revenue Up, Revenue Down, Cost Up, or Cost Down</td></tr><tr><td>Baseline</td><td>The current state before this Feature ships (in the relevant unit)</td></tr><tr><td>Delta</td><td>The change this Feature is expected to produce (as a number or percentage)</td></tr><tr><td>Start Month</td><td>Which month the impact begins (month 1 = launch)</td></tr><tr><td>Ramp Type</td><td>How the impact builds over time: Immediate, Linear, or Exponential</td></tr><tr><td>Confidence</td><td>The reliability of this estimate: High, Medium, or Low</td></tr></tbody></table><h3 id="scenarios" tabindex="-1">Scenarios <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;Scenarios&quot;">​</a></h3><p>Each assumption can have <strong>Bull</strong> and <strong>Bear</strong> scenario values — alternative estimates for optimistic and pessimistic cases. When scenarios are defined, Lodestone can calculate metrics across all three scenarios (Base, Bull, Bear) simultaneously.</p><h3 id="financial-metrics" tabindex="-1">Financial Metrics <a class="header-anchor" href="#financial-metrics" aria-label="Permalink to &quot;Financial Metrics&quot;">​</a></h3><p>Lodestone calculates the following metrics from the model&#39;s assumptions:</p><table tabindex="0"><thead><tr><th>Metric</th><th>What it measures</th></tr></thead><tbody><tr><td>NPV</td><td>Net Present Value — the present-day value of all future cash flows, discounted by your rate</td></tr><tr><td>ROI</td><td>Return on investment over the forecast period</td></tr><tr><td>IRR</td><td>Internal rate of return</td></tr><tr><td>Payback Period</td><td>How many months until cumulative returns exceed cumulative costs</td></tr></tbody></table><p>Metrics are recalculated automatically whenever assumptions are added or changed.</p><h3 id="discount-rate" tabindex="-1">Discount Rate <a class="header-anchor" href="#discount-rate" aria-label="Permalink to &quot;Discount Rate&quot;">​</a></h3><p>The discount rate is used to calculate NPV. It represents the minimum acceptable return on investment (or cost of capital). The default rate is 12%. It can be set per-model or configured as an org-wide default in Financial Forecast settings.</p><hr><h2 id="the-compare-view" tabindex="-1">The Compare View <a class="header-anchor" href="#the-compare-view" aria-label="Permalink to &quot;The Compare View&quot;">​</a></h2><p>Beyond individual Feature models, Lodestone provides an <strong>organization-level Compare view</strong> accessible from Financial Forecast. This view shows all Features that have financial models in a single ranked table, sorted by NPV by default. It lets you compare the financial cases for multiple Features side-by-side to inform prioritization decisions.</p><hr><h2 id="evidence-linking" tabindex="-1">Evidence Linking <a class="header-anchor" href="#evidence-linking" aria-label="Permalink to &quot;Evidence Linking&quot;">​</a></h2><p>Assumptions can be linked to customer quotes already associated with a Feature. This allows you to ground financial estimates in real customer signal — for example, linking a revenue assumption to a quote from a customer who described their willingness to pay. Evidence links appear in the model and serve as an audit trail for how assumptions were justified.</p><hr><h2 id="guided-intake" tabindex="-1">Guided Intake <a class="header-anchor" href="#guided-intake" aria-label="Permalink to &quot;Guided Intake&quot;">​</a></h2><p>When creating a new model, Lodestone offers a <strong>Guided Intake</strong> flow — a conversational step-by-step assistant that asks questions to help you populate assumptions. This is the recommended starting point for users who are new to financial modeling or building a model for the first time.</p><p>Guided Intake produces a pre-populated model that you can refine, rather than starting from a blank slate.</p><hr><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Models can be exported as an <strong>Excel (.xlsx) file</strong>, which includes the full assumption set, scenario values, and calculated metrics. This is useful for sharing with finance teams, including in business cases, or maintaining records outside Lodestone.</p><hr><h2 id="how-financial-forecast-relates-to-the-rest-of-lodestone" tabindex="-1">How Financial Forecast Relates to the Rest of Lodestone <a class="header-anchor" href="#how-financial-forecast-relates-to-the-rest-of-lodestone" aria-label="Permalink to &quot;How Financial Forecast Relates to the Rest of Lodestone&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object</th><th>Relationship</th></tr></thead><tbody><tr><td>Features</td><td>Each model belongs to one Feature. The Feature&#39;s name, description, and quotes are all accessible within the forecast context.</td></tr><tr><td>Extracts / Quotes</td><td>Customer quotes linked to a Feature can be attached to individual assumptions as evidence.</td></tr><tr><td>Settings</td><td>Org-level defaults for discount rate, labor rate, fiscal year start, and launch date are configured in Financial Forecast settings.</td></tr></tbody></table><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for creating models, entering assumptions, and exporting forecasts.</em></p>',45)])])}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
